mapper.select:
SELECT er.role_id
FROM sys_role_employee er
WHERE er.employee_id = #{employeeId}

SELECT employee.employee_id, employee.login_name, employee.login_pwd, employee.actual_name, employee.phone, employee.department_id, employee.disabled_flag, employee.remark, employee.update_time, employee.create_time FROM sys_role_employee left join employee on sys_role_employee.employee_id = employee.employee_id left join sys_role on sys_role_employee.role_id = sys_role.role_id
AND ( INSTR(employee.actual_name,#{queryForm.keywords}) OR INSTR(employee.phone,#{queryForm.keywords}) OR INSTR(employee.login_name,#{queryForm.keywords}) )
AND sys_role_employee.role_id = #{queryForm.roleId}

mapper.delete:
DELETE
FROM sys_role_employee
WHERE role_id = #{roleId}
  and employee_id = #{employeeId}

DELETE FROM sys_role_employee
WHERE role_id = #{roleId} and employee_id in

    #{item}
